// src/rules/interaction/interactRunner.js
//
// Lightweight hook runner for interactable entities.
// Mirrors the usePipeline/before+on+after pattern from the items system.
//
// Context exposed to every hook:
//   ctx.world      — full world (needed for complex ops like createFrom, dealDamage)
//   ctx.actor      — entity ID of the acting entity
//   ctx.targetId   — entity ID of the interactable target
//   ctx.params     — Interactable.params (static data on the archetype)
//   ctx.intent     — the InteractIntent data (mode, recipe, itemId, …)
//   ctx.cancelled  — boolean, set by ctx.cancel()
//   ctx.cancelReason — { code, message } or null
//   ctx.cancel(code, message) — abort remaining hook phases
//   ctx.emit(event, data) — convenience alias for world.emit
//   ctx.data       — mutable bag for sharing state between hook phases

import { INTERACT_PAYLOADS } from "../content/interaction/interactPayloads.js";
import { resolveActionMenu } from "../content/interaction/actionMenus.js";
import { InteractionChoicePrompted } from "../../events/InteractionChoicePrompted.js";
import { executeVerbRule } from "../kernel/verbRule.js";
import { getAuthoredInteractable } from "./interactableRegistry.js";

/**
 * @param {any} world
 * @param {number} actor
 * @param {number} targetId
 * @param {any|null} params
 * @param {any|null} intent
 * @returns {{ cancelled: boolean, cancelReason: any, data: any }}
 */
export function createInteractContext(world, actor, targetId, params, intent) {
  const ctx = {
    world,
    actor,
    targetId,
    params,
    intent,
    data: {},
    cancelled: false,
    cancelReason: null,
    /** @param {string} code @param {string} [message] */
    cancel(code, message = "") {
      this.cancelled = true;
      this.cancelReason = { code: String(code), message: String(message) };
    },
    /** @param {string} event @param {any} data */
    emit(event, data) {
      this.world.emit?.(event, data);
    },
  };
  return ctx;
}

/**
 * Look up and run all hooks for an action.
 * Returns true if a payload was found, false if the action is unregistered.
 *
 * @param {string} action
 * @param {any} world
 * @param {number} actor
 * @param {number} targetId
 * @param {any|null} params
 * @param {any|null} intent
 * @returns {boolean}
 */
export function runInteractHooks(action, world, actor, targetId, params, intent) {
  // If the action has a multi-option menu and no mode was chosen yet,
  // emit the chooser event and bail — the UI will re-dispatch with a mode.
  const payload = getAuthoredInteractable(action) || INTERACT_PAYLOADS[action];
  const authoredActions = payload?.actions;
  const menu = authoredActions
    ? (typeof authoredActions === "function" ? authoredActions(world, targetId, { actor, intent, params }) : authoredActions)
    : resolveActionMenu(action, world, targetId);
  if (menu?.length && !intent?.mode) {
    world.emit(new InteractionChoicePrompted({ actor, targetId, action, options: menu }));
    return true;
  }

  if (!payload) return false;

  const ctx = createInteractContext(world, actor, targetId, params, intent);

  if (typeof payload.beforeInteract === "function") {
    payload.beforeInteract(ctx);
    if (ctx.cancelled) return true;
  }

  if (payload.verbs) {
    const verb = String(intent?.mode || payload.defaultVerb || Object.keys(payload.verbs)[0] || "");
    const rule = payload.verbs[verb];
    if (!rule) return false;
    const result = executeVerbRule(world, rule, {
      actor,
      primary: Number(intent?.itemId || targetId) | 0,
      target: targetId,
      params: {
        action,
        intent,
        interactableParams: params,
        forceOutcomeId: String(intent?.forceOutcomeId || ""),
      },
    });
    world.emit("interaction:result", result);
    return true;
  }

  if (typeof payload.onInteract === "function") {
    payload.onInteract(ctx);
  }

  if (!ctx.cancelled && typeof payload.afterInteract === "function") {
    payload.afterInteract(ctx);
  }

  return true;
}
// src/rules/systems/interactionSystem.js
//
// Thin dispatch layer. All interaction logic lives in:
//   src/content/interactables/                         (authored definitions)
//   src/rules/content/interaction/interactPayloads.js  (legacy definitions)
//   src/rules/interaction/interactRunner.js             (context + hook runner)
//
// To add a new interactable: author it with defineInteractable().
// This file never needs to change.

import { Interactable } from "../components/Interactable.js";
import { InteractIntent } from "../components/Intents/InteractIntent.js";
import { runInteractHooks } from "../interaction/interactRunner.js";
import { isEntityOnCurrentFloor } from "../utils/floorEntities.js";
import { defineExtension } from "../../lib/ecs-js/index.js";

/**
 * Dispatch a single interaction between actor and targetId.
 * Returns true if a hook payload was found and executed, false otherwise.
 *
 * @param {any} world
 * @param {number} actor
 * @param {number} targetId
 * @param {any|null} intent
 * @returns {boolean}
 */
export function InteractionSystem(world, actor, targetId, intent = null) {
  if (!isEntityOnCurrentFloor(world, targetId, { fallbackWhenNoDungeonState: true })) return false;
  const inter = world.get(targetId, Interactable);
  if (!inter) return false;
  return runInteractHooks(inter.action, world, actor, targetId, inter.params, intent);
}

/**
 * Per-tick system: drains the InteractIntent queue and dispatches each one.
 *
 * @param {any} world
 */
export function interactionSystem(world) {
  for (const [actor, intent] of world.query(InteractIntent)) {
    try {
      InteractionSystem(world, actor, intent.targetId || 0, intent);
    } catch (e) {
      console.error("[interactionSystem] dispatch failed:", e);
    }
    try { world.remove(actor, InteractIntent); } catch {}
  }
}

// ─── Bump-interact event listener ────────────────────────────────────────────

/**
 * Install a one-time bump:interact listener for movement-triggered interactions
 * (e.g. walking into a door). This bypasses the intent queue so bump actions
 * resolve immediately during movement.
 */
export const bumpInteractListenerExtension = defineExtension("jshack:rules:bumpInteract", (world) => {
  world.on("bump:interact", /** @param {{actor:number,target:number}} ev */ (ev) => {
    try {
      InteractionSystem(world, ev.actor, ev.target, { source: "bump" });
    } catch (e) {
      console.error("[interactionSystem] bump dispatch failed:", e);
    }
  });
});

/**
 * @param {any} world
 */
export function installBumpInteractListener(world) {
  world?.install?.(bumpInteractListenerExtension);
}
import { defineComponent } from "../../../lib/ecs-js/index.js";

// InteractIntent — actor wishes to interact with a target entity (e.g., door, chest)
//
// Fields:
//   targetId — the entity to interact with
//   mode     — optional sub-mode string (e.g. "brew", "offer")
//   recipe   — optional recipe key for crafting interactions
//   itemId   — optional item entity ID (e.g. altar offering selection)
export const InteractIntent = defineComponent("InteractIntent", {
	targetId: 0,
	mode: "",
	recipe: "",
	itemId: 0,
});

import { Consumable } from "../../components/Consumable.js";
import { Equipment, getEquippedSlot } from "../../components/Equipment.js";
import { MaterialState } from "../../components/MaterialState.js";
import { findUsePayload } from "../../content/items/usePayloads.js";
import { queueShopDebtForUnauthorizedUse } from "../../utils/shopClaims.js";
import { interceptUseForWaterDamage } from "../../utils/waterExposure.js";
import { getCatalogItem } from "../../data/itemCatalog.js";
import { itemAbilityPipeline } from "./itemAbilityPipeline.js";

/**
 * @param {any} value
 */
function normalizeUseHookResult(value) {
  if (typeof value === "boolean") return { consumed: value };
  if (value && typeof value === "object") {
    return {
      consumed: value.consumed === true,
      cancelled: value.cancelled === true,
      code: value.code,
      message: value.message,
      consumesTurn: value.consumesTurn,
      detail: value.detail,
      spellId: value.spellId,
    };
  }
  return { consumed: false };
}

function shouldCreateShopDebtForUse({ info, identity, hookResult }) {
