      try { window.removeEventListener('keydown', _escHandler); } catch {}
      _escHandler = null;
    }
    if (_cancelUiHandler) {
      try { window.removeEventListener('ui:cancelChanneling', _cancelUiHandler); } catch {}
      _cancelUiHandler = null;
    }
