      if (ev.key === 'Escape' || ev.keyCode === 27) {

    // Install cancel handler for mobile cancel button
    _cancelUiHandler = () => cancelChanneling();
    try { window.addEventListener('ui:cancelChanneling', _cancelUiHandler); } catch {}

